+
+        <TabsContent value="documents">
+          <DocumentList projectId={id} />
+        </TabsContent>
+
+        <TabsContent value="compliance">
+          <ComplianceList projectId={id} />
+        </TabsContent>
       </Tabs>

       <QuoteBuilder
         projectId={id}
         open={showQuoteBuilder}
         onOpenChange={setShowQuoteBuilder}
         onCreated={(quoteId) => {
           setShowQuoteBuilder(false);
           setViewingQuoteId(quoteId);
