import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";
import type { RFQ, RFQItem, RFQResponse } from "@/types/api";

export function useRFQs(projectId: string, params?: { page?: number; page_size?: number }) {
  return useQuery({
    queryKey: ["rfqs", projectId, params],
    queryFn: () => api.listRFQs(projectId, params),
  });
}

export function useRFQ(rfqId: string) {
  return useQuery({
    queryKey: ["rfq", rfqId],
    queryFn: () => api.getRFQ(rfqId),
    enabled: !!rfqId,
  });
}

export function useCreateRFQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ projectId, data }: { projectId: string; data: Partial<RFQ> }) =>
      api.createRFQ(projectId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfqs", variables.projectId] });
    },
  });
}

export function useUpdateRFQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, data }: { rfqId: string; data: Partial<RFQ> }) =>
      api.updateRFQ(rfqId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfq", variables.rfqId] });
      queryClient.invalidateQueries({ queryKey: ["rfqs"] });
    },
  });
}

export function useDeleteRFQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, projectId }: { rfqId: string; projectId: string }) =>
      api.deleteRFQ(rfqId),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfqs", variables.projectId] });
    },
  });
}

export function useAddRFQItem() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, data }: { rfqId: string; data: Partial<RFQItem> }) =>
      api.addRFQItem(rfqId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfq", variables.rfqId] });
    },
  });
}

export function useRemoveRFQItem() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, itemId }: { rfqId: string; itemId: string }) =>
      api.removeRFQItem(rfqId, itemId),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfq", variables.rfqId] });
    },
  });
}

export function useSendRFQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (rfqId: string) => api.sendRFQ(rfqId),
    onSuccess: (_data, rfqId) => {
      queryClient.invalidateQueries({ queryKey: ["rfq", rfqId] });
      queryClient.invalidateQueries({ queryKey: ["rfqs"] });
    },
  });
}

export function useCloseRFQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (rfqId: string) => api.closeRFQ(rfqId),
    onSuccess: (_data, rfqId) => {
      queryClient.invalidateQueries({ queryKey: ["rfq", rfqId] });
      queryClient.invalidateQueries({ queryKey: ["rfqs"] });
    },
  });
}

export function useAwardRFQ() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, vendorId }: { rfqId: string; vendorId: string }) =>
      api.awardRFQ(rfqId, vendorId),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfq", variables.rfqId] });
      queryClient.invalidateQueries({ queryKey: ["rfqs"] });
    },
  });
}

export function useRFQResponses(rfqId: string) {
  return useQuery({
    queryKey: ["rfqResponses", rfqId],
    queryFn: () => api.listRFQResponses(rfqId),
    enabled: !!rfqId,
  });
}

export function useSubmitRFQResponse() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, data }: { rfqId: string; data: { vendor_id: string; unit_price?: number; delivery_days?: number; validity_days?: number; notes?: string } }) =>
      api.submitRFQResponse(rfqId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfqResponses", variables.rfqId] });
      queryClient.invalidateQueries({ queryKey: ["rfq", variables.rfqId] });
    },
  });
}

export function useUpdateRFQResponse() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ rfqId, responseId, data }: { rfqId: string; responseId: string; data: { status?: string; unit_price?: number; delivery_days?: number; validity_days?: number; notes?: string } }) =>
      api.updateRFQResponse(rfqId, responseId, data),
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: ["rfqResponses", variables.rfqId] });
      queryClient.invalidateQueries({ queryKey: ["rfq", variables.rfqId] });
    },
  });
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useRFQs, useDeleteRFQ } from "@/hooks/useRFQs";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { ArrowLeft, ArrowRight, Plus, Send, Award, XCircle } from "lucide-react";
import type { RFQ } from "@/types/api";

interface RFQListProps {
  projectId: string;
  onCreateNew?: () => void;
  onViewRFQ?: (rfq: RFQ) => void;
  onSendRFQ?: (rfq: RFQ) => void;
  onAwardRFQ?: (rfq: RFQ) => void;
  onCloseRFQ?: (rfq: RFQ) => void;
}

const statusColors: Record<string, string> = {
  draft: "bg-gray-100 text-gray-800",
  sent: "bg-blue-100 text-blue-800",
  under_review: "bg-yellow-100 text-yellow-800",
  closed: "bg-orange-100 text-orange-800",
  awarded: "bg-green-100 text-green-800",
};

export function RFQList({
  projectId,
  onCreateNew,
  onViewRFQ,
  onSendRFQ,
  onAwardRFQ,
  onCloseRFQ,
}: RFQListProps) {
  const [page, setPage] = useState(1);
  const pageSize = 20;

  const { data, isLoading } = useRFQs(projectId, { page, page_size: pageSize });
  const deleteRFQ = useDeleteRFQ();

  const rfqs = data?.items ?? [];
  const total = data?.total ?? 0;
  const totalPages = Math.ceil(total / pageSize);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-semibold">RFQs</h2>
