                      <TableCell>
                        <span className={`px-2 py-1 rounded text-xs ${statusColors[rfq.status] || "bg-gray-100 text-gray-800"}`}>
                          {rfq.status.replace("_", " ")}
                        </span>
                      </TableCell>
                      <TableCell>{new Date(rfq.created_at).toLocaleDateString()}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
