                            <Button variant="ghost" size="sm" onClick={() => onSendRFQ(rfq)}>
                              <Send className="h-4 w-4" />
                            </Button>
                          )}
                          {onAwardRFQ && rfq.status === "under_review" && (
                            <Button variant="ghost" size="sm" onClick={() => onAwardRFQ(rfq)}>
                              <Award className="h-4 w-4" />
                            </Button>
                          )}
                          {onCloseRFQ && rfq.status === "sent" && (
                            <Button variant="ghost" size="sm" onClick={() => onCloseRFQ(rfq)}>
                              <XCircle className="h-4 w-4" />
                            </Button>
