interface RFQFormProps {
  rfq?: Partial<RFQ>;
  items?: RFQItem[];
  onSave: (data: { title: string; notes?: string }) => void;
  onCancel: () => void;
  onAddItem?: (item: { description: string; quantity: number; unit: string }) => void;
  onRemoveItem?: (itemId: string) => void;
}

export function RFQForm({ rfq, items = [], onSave, onCancel, onAddItem, onRemoveItem }: RFQFormProps) {
  const [title, setTitle] = useState(rfq?.title ?? "");
  const [notes, setNotes] = useState(rfq?.notes ?? "");
  const [newItemDesc, setNewItemDesc] = useState("");
  const [newItemQty, setNewItemQty] = useState("");
  const [newItemUnit, setNewItemUnit] = useState("Nos");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ title, notes: notes || undefined });
  };

  const handleAddItem = () => {
    if (onAddItem && newItemDesc && newItemQty) {
      onAddItem({ description: newItemDesc, quantity: parseFloat(newItemQty), unit: newItemUnit });
      setNewItemDesc("");
      setNewItemQty("");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle>{rfq?.id ? "Edit RFQ" : "Create RFQ"}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <Label htmlFor="title">Title</Label>
            <Input
              id="title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="RFQ for HVAC materials"
              required
            />
          </div>
          <div>
            <Label htmlFor="notes">Notes</Label>
            <Input
              id="notes"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Additional notes..."
            />
          </div>

          {onAddItem && (
            <div className="space-y-2">
              <Label>Items</Label>
              {items.map((item, idx) => (
                <div key={item.id || idx} className="flex items-center gap-2">
                  <span className="flex-1">{item.description}</span>
                  <span className="text-sm text-muted-foreground">{item.quantity} {item.unit}</span>
                  {onRemoveItem && (
                    <Button type="button" variant="ghost" size="sm" onClick={() => onRemoveItem(item.id)}>
                      Remove
                    </Button>
                  )}
                </div>
              ))}
              <div className="flex items-end gap-2">
                <div className="flex-1">
                  <Label className="text-xs">Description</Label>
                  <Input
                    value={newItemDesc}
                    onChange={(e) => setNewItemDesc(e.target.value)}
                    placeholder="Item description"
                  />
                </div>
                <div className="w-24">
                  <Label className="text-xs">Qty</Label>
                  <Input
                    type="number"
                    value={newItemQty}
                    onChange={(e) => setNewItemQty(e.target.value)}
                    placeholder="0"
                  />
                </div>
                <div className="w-20">
                  <Label className="text-xs">Unit</Label>
                  <Input
                    value={newItemUnit}
                    onChange={(e) => setNewItemUnit(e.target.value)}
                    placeholder="Nos"
                  />
                </div>
                <Button type="button" variant="outline" onClick={handleAddItem}>Add</Button>
              </div>
            </div>
          )}

          <div className="flex justify-end gap-2">
            <Button type="button" variant="outline" onClick={onCancel}>Cancel</Button>
            <Button type="submit">{rfq?.id ? "Update" : "Create"} RFQ</Button>
          </div>
        </CardContent>
      </Card>
    </form>
  );
}

import { useQuery } from "@tanstack/react-query";
import { useRFQ, useSendRFQ, useCloseRFQ, useAwardRFQ } from "@/hooks/useRFQs";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Send, XCircle, Award } from "lucide-react";
import type { RFQ } from "@/types/api";

interface RFQDetailProps {
  rfqId: string;
  onAward?: (rfq: RFQ, vendorId: string) => void;
}

const statusColors: Record<string, string> = {
  draft: "bg-gray-100 text-gray-800",
  sent: "bg-blue-100 text-blue-800",
  under_review: "bg-yellow-100 text-yellow-800",
  closed: "bg-orange-100 text-orange-800",
  awarded: "bg-green-100 text-green-800",
};

export function RFQDetail({ rfqId, onAward }: RFQDetailProps) {
  const { data: rfq, isLoading } = useRFQ(rfqId);
  const sendRFQ = useSendRFQ();
  const closeRFQ = useCloseRFQ();
  const awardRFQ = useAwardRFQ();

  if (isLoading) {
    return <div className="p-4 text-center">Loading...</div>;
  }

  if (!rfq) {
    return <div className="p-4 text-center">RFQ not found</div>;
  }

  const handleSend = async () => {
    await sendRFQ.mutateAsync(rfqId);
  };

  const handleClose = async () => {
    await closeRFQ.mutateAsync(rfqId);
  };

  const handleAward = (vendorId: string) => {
    if (onAward) {
      onAward(rfq, vendorId);
    } else {
      awardRFQ.mutate({ rfqId, vendorId });
    }
  };

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle>{rfq.title}</CardTitle>
          <div className="flex items-center gap-2">
            <span className={`px-2 py-1 rounded text-xs ${statusColors[rfq.status] || "bg-gray-100 text-gray-800"}`}>
              {rfq.status.replace("_", " ")}
            </span>
            {rfq.status === "draft" && (
              <Button size="sm" onClick={handleSend} disabled={sendRFQ.isPending}>
                <Send className="mr-1 h-4 w-4" /> Send
              </Button>
            )}
            {rfq.status === "sent" && (
              <Button size="sm" variant="outline" onClick={handleClose} disabled={closeRFQ.isPending}>
                <XCircle className="mr-1 h-4 w-4" /> Close
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {rfq.notes && (
            <div>
              <span className="text-sm font-medium">Notes:</span>
              <p className="text-sm text-muted-foreground">{rfq.notes}</p>
            </div>
          )}

          {rfq.submission_deadline && (
            <div>
              <span className="text-sm font-medium">Deadline:</span>
              <p className="text-sm text-muted-foreground">{new Date(rfq.submission_deadline).toLocaleDateString()}</p>
            </div>
          )}
        </CardContent>
      </Card>

      {rfq.items && rfq.items.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Items</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Description</TableHead>
                  <TableHead>Quantity</TableHead>
                  <TableHead>Unit</TableHead>
                  <TableHead>Target Rate</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {rfq.items.map((item) => (
                  <TableRow key={item.id}>
                    <TableCell>{item.description}</TableCell>
                    <TableCell>{item.quantity}</TableCell>
                    <TableCell>{item.unit}</TableCell>
                    <TableCell>{item.target_rate ? `₹${item.target_rate}` : "—"}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}

      {rfq.responses && rfq.responses.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Vendor Responses</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Vendor</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Unit Price</TableHead>
                  <TableHead>Total Price</TableHead>
                  <TableHead>Delivery Days</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {rfq.responses.map((response) => (
                  <TableRow key={response.id}>
                    <TableCell>{response.vendor_name || response.vendor_id}</TableCell>
                    <TableCell>
                      <span className={`px-2 py-1 rounded text-xs ${
                        response.status === "selected" ? "bg-green-100 text-green-800" :
                        response.status === "rejected" ? "bg-red-100 text-red-800" :
                        response.status === "submitted" ? "bg-blue-100 text-blue-800" :
                        "bg-gray-100 text-gray-800"
                      }`}>
                        {response.status}
                      </span>
                    </TableCell>
                    <TableCell>{response.unit_price ? `₹${response.unit_price}` : "—"}</TableCell>
                    <TableCell>{response.total_price ? `₹${response.total_price}` : "—"}</TableCell>
                    <TableCell>{response.delivery_days ?? "—"}</TableCell>
                    <TableCell>
                      {rfq.status === "under_review" && response.status === "submitted" && (
                        <Button size="sm" variant="outline" onClick={() => handleAward(response.vendor_id)}>
                          <Award className="h-4 w-4" />
                        </Button>
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { RFQ, RFQResponse } from "@/types/api";

interface RFQComparisonProps {
  rfq: RFQ;
}

export function RFQComparison({ rfq }: RFQComparisonProps) {
  if (!rfq.items || rfq.items.length === 0 || !rfq.responses || rfq.responses.length === 0) {
    return (
      <Card>
        <CardContent className="pt-6">
          <p className="text-center text-muted-foreground">No responses to compare</p>
        </CardContent>
      </Card>
    );
  }

  const submittedResponses = rfq.responses.filter((r) => r.status === "submitted" || r.status === "selected");

  if (submittedResponses.length < 2) {
    return (
      <Card>
        <CardContent className="pt-6">
          <p className="text-center text-muted-foreground">Need at least 2 vendor responses to compare</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Vendor Comparison</CardTitle>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-1/4">Item</TableHead>
              {submittedResponses.map((response) => (
                <TableHead key={response.id} className="text-center">
                  {response.vendor_name || response.vendor_id.slice(0, 8)}
                  {response.status === "selected" && (
                    <span className="ml-1 text-xs text-green-600 font-normal">(Selected)</span>
                  )}
                </TableHead>
              ))}
            </TableRow>
          </TableHeader>
          <TableBody>
            {rfq.items.map((item) => {
              const prices = submittedResponses.map((r) => ({
                response: r,
                total: r.total_price ?? r.unit_price ? (r.unit_price ?? 0) * Number(item.quantity) : null,
              }));

              const validTotals = prices
                .map((p) => p.total)
                .filter((t): t is number => t !== null && t > 0);
              const lowestPrice = validTotals.length > 0 ? Math.min(...validTotals) : null;

              return (
                <TableRow key={item.id}>
                  <TableCell>
                    <div>
                      <p className="font-medium">{item.description}</p>
                      <p className="text-xs text-muted-foreground">
                        Qty: {item.quantity} {item.unit}
                        {item.target_rate && ` | Target: ₹${item.target_rate}`}
                      </p>
                    </div>
                  </TableCell>
                  {prices.map((priceInfo) => {
                    const isLowest = priceInfo.total === lowestPrice && lowestPrice !== null;
                    return (
                      <TableCell
                        key={priceInfo.response.id}
                        className={`text-center ${isLowest ? "bg-green-50" : ""}`}
                      >
                        <div>
                          {priceInfo.response.unit_price !== null ? (
                            <>
                              <p className={`font-medium ${isLowest ? "text-green-700" : ""}`}>
                                ₹{priceInfo.response.unit_price.toLocaleString()}
                              </p>
                              {priceInfo.total !== null && (
                                <p className="text-xs text-muted-foreground">
                                  Total: ₹{priceInfo.total.toLocaleString()}
                                </p>
                              )}
                            </>
                          ) : (
                            <span className="text-muted-foreground">—</span>
                          )}
                        </div>
                      </TableCell>
                    );
                  })}
                </TableRow>
              );
            })}

            <TableRow className="font-bold bg-slate-50">
              <TableCell>Grand Total</TableCell>
              {submittedResponses.map((response) => {
                const grandTotal = rfq.items!.reduce((sum, item) => {
                  const rate = response.unit_price ?? 0;
                  return sum + rate * Number(item.quantity);
                }, 0);
                const isLowest = submittedResponses.every((r) => {
                  if (r.id === response.id) return true;
                  const otherTotal = rfq.items!.reduce((sum, item) => {
                    const r = submittedResponses.find((resp) => resp.id === r.id);
                    return sum + (r?.unit_price ?? 0) * Number(item.quantity);
                  }, 0);
                  return grandTotal <= otherTotal;
                });
                return (
                  <TableCell key={response.id} className={`text-center ${isLowest ? "bg-green-100" : ""}`}>
                    ₹{grandTotal.toLocaleString()}
                  </TableCell>
                );
              })}
            </TableRow>
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import type { RFQ } from "@/types/api";

interface RFQResponseFormProps {
  rfq: RFQ;
  onSubmit: (data: {
    vendor_id: string;
    unit_price?: number;
    delivery_days?: number;
    validity_days?: number;
    notes?: string;
  }) => void;
  onCancel: () => void;
  onSelectVendor?: () => void;
}

export function RFQResponseForm({ rfq, onSubmit, onCancel, onSelectVendor }: RFQResponseFormProps) {
  const [vendorId, setVendorId] = useState("");
  const [unitPrice, setUnitPrice] = useState("");
  const [deliveryDays, setDeliveryDays] = useState("");
  const [validityDays, setValidityDays] = useState("");
  const [notes, setNotes] = useState("");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      vendor_id: vendorId,
      unit_price: unitPrice ? parseFloat(unitPrice) : undefined,
      delivery_days: deliveryDays ? parseInt(deliveryDays) : undefined,
      validity_days: validityDays ? parseInt(validityDays) : undefined,
      notes: notes || undefined,
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <Card>
        <CardHeader>
          <CardTitle>Submit Response</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {!onSelectVendor && (
            <div>
              <Label htmlFor="vendor_id">Vendor ID</Label>
              <Input
                id="vendor_id"
                value={vendorId}
                onChange={(e) => setVendorId(e.target.value)}
                placeholder="Enter vendor UUID"
                required
              />
            </div>
          )}

          {onSelectVendor && (
            <div className="mb-4">
              <Button type="button" variant="outline" onClick={onSelectVendor}>
                Select Vendor
              </Button>
            </div>
          )}

          <div>
            <Label htmlFor="unit_price">Unit Price (per unit)</Label>
            <Input
              id="unit_price"
              type="number"
              step="0.01"
              value={unitPrice}
              onChange={(e) => setUnitPrice(e.target.value)}
              placeholder="0.00"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="delivery_days">Delivery Days</Label>
              <Input
                id="delivery_days"
                type="number"
                value={deliveryDays}
